import argparse
from pathlib import Path

import pandas as pd

# Project root directory
PROJECT_ROOT = Path(__file__).resolve().parents[2]

# Input: generated by audit.py
DEFAULT_INPUT = PROJECT_ROOT / "reports" / "annotation_audit.csv"

# Output: high and medium priority review file
DEFAULT_OUTPUT = PROJECT_ROOT / "reports" / "annotation_audit_high_medium_review.csv"

REVIEW_PRIORITIES = {"HIGH", "MEDIUM"}

LABEL_COLUMNS = [
    "sentiment",
    "actionability",
    "toxicity",
    "question_type",
]


def prepare_review(
    input_path: Path,
    output_path: Path,
) -> pd.DataFrame:

    if not input_path.exists():
        raise FileNotFoundError(
            f"Audit file not found: {input_path}\nRun: python -m src.annotation.audit"
        )

    # Load audit results
    df = pd.read_csv(
        input_path,
        encoding="utf-8-sig",
        dtype={"comment_id": "string"},
        keep_default_na=False,
    )

    required_columns = {
        "row_number",
        "comment_id",
        "text",
        "priority",
        *LABEL_COLUMNS,
    }

    missing_columns = required_columns - set(df.columns)

    if missing_columns:
        raise ValueError(f"Missing columns: {sorted(missing_columns)}")

    # Keep HIGH and MEDIUM only
    review_df = df.loc[df["priority"].isin(REVIEW_PRIORITIES)].copy()

    # Ensure editable review fields exist
    if "review_status" not in review_df.columns:
        review_df["review_status"] = "PENDING"

    if "reviewer_notes" not in review_df.columns:
        review_df["reviewer_notes"] = ""

    if "approved_correction" not in review_df.columns:
        review_df["approved_correction"] = ""

    # Add separate suggested labels.
    # These are deliberately empty until a human
    # reviewer proposes corrections.
    for column in LABEL_COLUMNS:
        suggested_column = f"suggested_{column}"

        if suggested_column not in review_df.columns:
            review_df[suggested_column] = ""

    # Sort by priority, then original row number
    priority_order = {
        "HIGH": 0,
        "MEDIUM": 1,
    }

    review_df["_priority_order"] = review_df["priority"].map(priority_order)

    review_df["row_number"] = pd.to_numeric(
        review_df["row_number"],
        errors="raise",
    ).astype(int)

    review_df = (
        review_df.sort_values(
            ["_priority_order", "row_number"],
            kind="stable",
        )
        .drop(columns=["_priority_order"])
        .reset_index(drop=True)
    )

    # Prevent accidentally overwriting an existing
    # file containing manual review work.
    if output_path.exists():
        raise FileExistsError(
            f"Review file already exists: {output_path}\n"
            "Rename or back up the existing file first."
        )

    output_path.parent.mkdir(
        parents=True,
        exist_ok=True,
    )

    review_df.to_csv(
        output_path,
        index=False,
        encoding="utf-8-sig",
    )

    return review_df


def main():
    parser = argparse.ArgumentParser(
        description="Prepare high/medium annotation review"
    )

    parser.add_argument(
        "--input",
        type=Path,
        default=DEFAULT_INPUT,
    )

    parser.add_argument(
        "--output",
        type=Path,
        default=DEFAULT_OUTPUT,
    )

    args = parser.parse_args()

    review_df = prepare_review(
        args.input,
        args.output,
    )

    print("=" * 60)
    print("ANNOTATION REVIEW PREPARATION")
    print("=" * 60)

    print(f"Total review candidates: {len(review_df)}")

    print("\nPriority distribution:")
    for priority in ["HIGH", "MEDIUM"]:
        count = int((review_df["priority"] == priority).sum())
        print(f"  {priority}: {count}")

    print("\nReview status: PENDING")
    print(f"\nGenerated file:\n  {args.output}")

    print("\nOriginal dataset was not modified.")


if __name__ == "__main__":
    main()
